package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;

final class FieldDispatchAcceptance {
 static String route(String parent,String task){return "/api/openservice/records/incident/"+parent+"/field-dispatch/"+task;}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{return ProblemInvestigationsAcceptance.result(r);}
 static Map<String,Object> page(WorkflowSupport h,String parent,String task,String user)throws Exception{return result(h.get(route(parent,task),auth(user)));}
 static String uid(WorkflowSupport h,String user)throws Exception{try(var db=h.store.open()){return RecordAccess.owner(db,user);}}
 static Map<String,Object> body(WorkflowSupport h,String parent,String task,String operation)throws Exception{var p=page(h,parent,task,"admin");var b=map("operation",operation,"revision",object(p.get("dispatch")).get("revision"),"task_revision",object(p.get("task")).get("revision"),"record_revision",Integer.parseInt(object(p.get("parent")).get("sys_mod_count").toString()));if(operation.equals("assign"))b.putAll(map("technician_id",uid(h,"TaskOne"),"start","2030-01-07T09:00:00Z","end","2030-01-07T10:00:00Z","location","Building A <script>safe</script>"));else b.put("reason","Reviewed field dispatch decision");return b;}
 static Map<String,Object> act(WorkflowSupport h,String parent,String task,String operation,String user)throws Exception{return result(h.json("POST",route(parent,task),body(h,parent,task,operation),auth(user)));}
 static Map<String,Object> availability(WorkflowSupport h,String user,boolean active)throws Exception{String identity=uid(h,user);int revision;try(var db=h.store.open()){revision=(int)db.count("SELECT COALESCE((SELECT revision FROM os_field_availability WHERE user_id=?),0)",identity);}return map("username",user,"calendar_id","FieldDay","active",active,"revision",revision);}
 static void available(WorkflowSupport h,String user,boolean active)throws Exception{result(h.json("POST","/api/openservice/field-availability",availability(h,user,active),auth("admin")));}
 static String[] setup(WorkflowSupport h)throws Exception{String group=WorkTasksAcceptance.setup(h),parent=h.add("incident").get("sys_id").toString();ChangeSchedulingAcceptance.calendar(h,"FieldDay","UTC","08:00","18:00",List.of(1,2,3,4,5),List.of());available(h,"TaskOne",true);available(h,"TaskTwo",true);WorkTasksAcceptance.configure(h,parent);String task=WorkTasksAcceptance.create(h,parent,group,List.of(),true);return new String[]{parent,task,group};}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String parent=ids[0],task=ids[1];assertEquals("unassigned",object(page(h,parent,task,"TaskOne").get("dispatch")).get("status"));var old=body(h,parent,task,"assign");result(h.json("POST",route(parent,task),old,auth("TaskTwo")));assertEquals(409,h.json("POST",route(parent,task),old,auth("admin")).statusCode());assertEquals(409,h.json("POST",WorkTasksAcceptance.api(parent),WorkTasksAcceptance.command(h,parent,"claim",task),auth("TaskOne")).statusCode());assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"assign"),auth("admin")).statusCode());assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"accept"),auth("TaskTwo")).statusCode());act(h,parent,task,"reject","TaskOne");assertEquals("queued",object(page(h,parent,task,"admin").get("task")).get("state"));act(h,parent,task,"assign","admin");act(h,parent,task,"release","TaskTwo");act(h,parent,task,"assign","admin");act(h,parent,task,"accept","TaskOne");assertEquals("working",object(page(h,parent,task,"TaskOne").get("task")).get("state"));assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"reject"),auth("TaskOne")).statusCode());var requeue=WorkTasksAcceptance.command(h,parent,"requeue",task);requeue.put("reason","Requested reassignment");assertEquals(409,h.json("POST",WorkTasksAcceptance.api(parent),requeue,auth("admin")).statusCode());act(h,parent,task,"release","TaskTwo");assertEquals("",object(page(h,parent,task,"admin").get("task")).get("assignee_id"));act(h,parent,task,"assign","admin");act(h,parent,task,"accept","TaskOne");WorkTasksAcceptance.act(h,parent,task,"complete","TaskOne","Visit completed and customer informed");assertEquals("complete",object(page(h,parent,task,"admin").get("dispatch")).get("status"));assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"assign"),auth("admin")).statusCode());assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"release"),auth("admin")).statusCode());new Store(h.environment);assertEquals("complete",object(page(h,parent,task,"admin").get("dispatch")).get("status"));try(var db=h.store.open()){assertTrue(db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action LIKE 'field.dispatch_%'",parent)>=9);}
  String optional=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);act(h,parent,optional,"assign","admin");WorkTasksAcceptance.state(h,parent,"2",200);WorkTasksAcceptance.state(h,parent,"6",409);act(h,parent,optional,"accept","TaskOne");WorkTasksAcceptance.act(h,parent,optional,"cancel","TaskOne","Visit no longer needed");assertEquals("cancelled",object(page(h,parent,optional,"admin").get("dispatch")).get("status"));WorkTasksAcceptance.state(h,parent,"6",200);assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"release"),auth("admin")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/incident/"+parent,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_field_dispatch"));}
 }
 static void conflicts(WorkflowSupport h)throws Exception{
  var ids=setup(h);String parent=ids[0],a=ids[1],b=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),true);var one=body(h,parent,a,"assign");var two=body(h,parent,b,"assign");try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return h.json("POST",route(parent,a),one,auth("admin")).statusCode();});var y=pool.submit(()->{start.await();return h.json("POST",route(parent,b),two,auth("admin")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(x.get(),y.get()));}
  String chosen=object(page(h,parent,a,"admin").get("dispatch")).get("status").equals("assigned")?a:b,other=chosen.equals(a)?b:a;var conflict=h.json("POST",route(parent,other),body(h,parent,other,"assign"),auth("admin"));assertEquals(409,conflict.statusCode());assertTrue(html(conflict).contains("another reserved visit"));var adjacent=body(h,parent,other,"assign");adjacent.put("start","2030-01-07T10:00:00Z");adjacent.put("end","2030-01-07T11:00:00Z");result(h.json("POST",route(parent,other),adjacent,auth("admin")));assertEquals(2,result(h.get("/api/openservice/field-service?limit=1",auth("TaskOne"))).get("total"));assertEquals(1,objects(result(h.get("/api/openservice/field-service?limit=1",auth("TaskOne"))).get("items")).size());assertNotNull(result(h.get("/api/openservice/field-service?limit=1",auth("TaskOne"))).get("next_offset"));assertNull(result(h.get("/api/openservice/field-service?limit=1&offset=1",auth("admin"))).get("next_offset"));assertEquals(0,result(h.get("/api/openservice/field-service",auth("TaskOther"))).get("total"));
  String hidden=h.add("incident").get("sys_id").toString();WorkTasksAcceptance.configure(h,hidden);String c=WorkTasksAcceptance.create(h,hidden,ids[2],List.of(),true);var booking=body(h,hidden,c,"assign");booking.put("start","2030-01-07T12:00:00Z");booking.put("end","2030-01-07T13:00:00Z");result(h.json("POST",route(hidden,c),booking,auth("admin")));ProblemInvestigationsAcceptance.access(h,"incident",hidden,"private",uid(h,"admin"));String d=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);var request=body(h,parent,d,"assign");request.put("start",booking.get("start"));request.put("end",booking.get("end"));var denied=h.json("POST",route(parent,d),request,auth("TaskTwo"));assertEquals(409,denied.statusCode());assertFalse(html(denied).contains(hidden));assertFalse(html(denied).contains(c));assertEquals(2,result(h.get("/api/openservice/field-service",auth("TaskOne"))).get("total"));
  act(h,parent,chosen,"release","admin");String dependency=WorkTasksAcceptance.create(h,parent,ids[2],List.of(chosen),false);assertEquals(409,h.json("POST",route(parent,dependency),body(h,parent,dependency,"assign"),auth("admin")).statusCode());WorkTasksAcceptance.act(h,parent,chosen,"claim","TaskOne","");assertEquals(409,h.json("POST",route(parent,chosen),body(h,parent,chosen,"assign"),auth("admin")).statusCode());WorkTasksAcceptance.act(h,parent,chosen,"complete","TaskOne","Prerequisite complete");
  String peer=h.add("incident").get("sys_id").toString();WorkTasksAcceptance.configure(h,peer);String peerTask=WorkTasksAcceptance.create(h,peer,ids[2],List.of(),true);var first=body(h,parent,d,"assign");var second=body(h,peer,peerTask,"assign");for(var candidate:List.of(first,second))candidate.putAll(map("technician_id",uid(h,"TaskTwo"),"start","2030-01-07T14:00:00Z","end","2030-01-07T15:00:00Z"));try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return h.json("POST",route(parent,d),first,auth("admin")).statusCode();});var y=pool.submit(()->{start.await();return h.json("POST",route(peer,peerTask),second,auth("admin")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(x.get(),y.get()));}String twoId=uid(h,"TaskTwo");try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_field_dispatch WHERE technician_id=? AND status='assigned'",twoId));}

 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String parent=ids[0],task=ids[1];for(String user:List.of("TaskOther","TaskReader"))assertEquals(403,h.get(route(parent,task),auth(user)).statusCode());assertEquals(403,h.get("/api/openservice/field-availability",auth("TaskOne")).statusCode());assertEquals(403,h.json("POST","/api/openservice/field-availability",availability(h,"TaskOne",true),auth("TaskOne")).statusCode());act(h,parent,task,"assign","admin");
  available(h,"TaskOne",false);assertEquals(false,page(h,parent,task,"TaskOne").get("eligible"));assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"accept"),auth("TaskOne")).statusCode());available(h,"TaskOne",true);ChangeSchedulingAcceptance.calendar(h,"FieldDay","UTC","11:00","18:00",List.of(1,2,3,4,5),List.of());assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"accept"),auth("TaskOne")).statusCode());ChangeSchedulingAcceptance.calendar(h,"FieldDay","UTC","08:00","18:00",List.of(1,2,3,4,5),List.of("2030-01-07"));assertEquals(false,page(h,parent,task,"admin").get("eligible"));ChangeSchedulingAcceptance.calendar(h,"FieldDay","UTC","08:00","18:00",List.of(1,2,3,4,5),List.of());
  RecordScopesAcceptance.member(h,ids[2],uid(h,"TaskOne"),false);assertEquals(403,h.get(route(parent,task),auth("TaskOne")).statusCode());assertEquals(false,page(h,parent,task,"admin").get("eligible"));RecordScopesAcceptance.member(h,ids[2],uid(h,"TaskOne"),true);
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}for(String field:List.of("description","state")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,h.get(route(parent,task),auth("TaskOne")).statusCode());assertEquals(false,page(h,parent,task,"admin").get("eligible"));assertEquals(0,result(h.get("/api/openservice/field-service",auth("TaskOne"))).get("total"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  var deniedSchema=new LinkedHashMap<>(original);deniedSchema.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",deniedSchema);try{assertEquals(0,result(h.get("/api/openservice/field-service",auth("TaskOne"))).get("total"));assertEquals(403,h.get(route(parent,task),auth("TaskOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  var schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(false,page(h,parent,task,"TaskOne").get("can_manage"));assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"accept"),auth("TaskOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  ProblemInvestigationsAcceptance.access(h,"incident",parent,"private",uid(h,"admin"));assertEquals(404,h.get(route(parent,task),auth("TaskOne")).statusCode());assertEquals(false,page(h,parent,task,"admin").get("eligible"));String technician=uid(h,"TaskOne");try(var db=h.store.open()){PlatformFoundationTest.bind(db);String admin=db.viewerId;assertThrows(Failure.class,()->FieldAvailability.eligible(db,"incident",parent,WorkTasks.task(db,parent,task),technician,ChangeScheduling.instant("2030-01-07T09:00:00Z"),ChangeScheduling.instant("2030-01-07T10:00:00Z")));assertEquals(admin,db.viewerId);assertEquals("admin",db.viewerRole);}ProblemInvestigationsAcceptance.access(h,"incident",parent,"workspace","");
  for(String column:List.of("active","role","password_reset_required")){try(var db=h.store.open()){db.update("UPDATE os_user SET "+column+"=? WHERE name='TaskOne'",column.equals("role")?"reader":column.equals("active")?0:1);db.connection.commit();}assertEquals(false,page(h,parent,task,"admin").get("eligible"));try(var db=h.store.open()){db.update("UPDATE os_user SET active=1,role='agent',password_reset_required=0 WHERE name='TaskOne'");db.connection.commit();}}
  act(h,parent,task,"accept","TaskOne");WorkTasksAcceptance.act(h,parent,task,"waive","admin","Reviewed optional visit");WorkTasksAcceptance.state(h,parent,"2",200);WorkTasksAcceptance.state(h,parent,"6",409);act(h,parent,task,"release","admin");WorkTasksAcceptance.state(h,parent,"6",200);
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String parent=ids[0],task=ids[1];for(String path:List.of(route(parent,task),"/api/openservice/field-availability")){assertEquals(405,h.json("DELETE",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?extra=1",auth("admin")).statusCode());}assertEquals(403,h.get("/api/openservice/field-service",auth("TaskReader")).statusCode());assertEquals(400,h.get("/api/openservice/field-service?extra=1",auth("admin")).statusCode());assertEquals(400,h.get("/api/openservice/field-service?limit=0",auth("admin")).statusCode());assertEquals(405,h.json("POST","/api/openservice/field-service",map(),auth("admin")).statusCode());assertEquals(404,h.get(route(parent,Values.id()),auth("admin")).statusCode());
  for(var changes:List.of(map("username","missing"),map("active","true"),map("calendar_id","missing"),map("extra",1),map("revision",-1))){var bad=availability(h,"TaskOne",true);bad.putAll(changes);assertEquals(400,h.json("POST","/api/openservice/field-availability",bad,auth("admin")).statusCode());}var stale=availability(h,"TaskOne",true);result(h.json("POST","/api/openservice/field-availability",stale,auth("admin")));assertEquals(409,h.json("POST","/api/openservice/field-availability",stale,auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/field-availability",map("revision","bad"),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/field-availability",map("revision","0","active","wrong"),auth("admin")).statusCode());
  for(var changes:List.of(map("operation","wrong"),map("extra",1),map("location"," "),map("location","x".repeat(241)),map("start","bad"),map("end","2030-01-07T08:00:00Z"),map("end","2030-01-08T10:00:00Z"),map("start","1970-01-01T09:00:00Z","end","1970-01-01T10:00:00Z"),map("task_revision",-1))){var bad=body(h,parent,task,"assign");bad.putAll(changes);assertEquals(400,h.json("POST",route(parent,task),bad,auth("admin")).statusCode());}for(String key:List.of("revision","task_revision","record_revision")){var bad=body(h,parent,task,"assign");bad.put(key,999);assertEquals(409,h.json("POST",route(parent,task),bad,auth("admin")).statusCode());}var bad=body(h,parent,task,"assign");bad.put("technician_id",uid(h,"TaskOther"));assertEquals(409,h.json("POST",route(parent,task),bad,auth("admin")).statusCode());assertEquals(400,h.protectedForm("/record/incident/"+parent+"/field-dispatch/"+task,map("revision","bad"),auth("admin")).statusCode());act(h,parent,task,"assign","admin");bad=body(h,parent,task,"reject");bad.put("reason","");assertEquals(400,h.json("POST",route(parent,task),bad,auth("TaskOne")).statusCode());
  try(var db=h.store.open()){db.update("UPDATE os_field_dispatch SET starts=?,ends=? WHERE task_id=?",ChangeScheduling.instant("2020-01-06T09:00:00Z"),ChangeScheduling.instant("2020-01-06T10:00:00Z"),task);db.connection.commit();}assertEquals(409,h.json("POST",route(parent,task),body(h,parent,task,"accept"),auth("TaskOne")).statusCode());act(h,parent,task,"release","admin");
  try(var db=h.store.open()){for(int n=2;n<200;n++){String identity=Values.id();db.update("INSERT INTO os_user(name,password,role,user_id) SELECT ?,password,'agent',? FROM os_user WHERE name='TaskOne'","FieldLimit"+n,identity);db.update("INSERT INTO os_field_availability(user_id,calendar_id,active,revision) VALUES(?,'FieldDay',1,1)",identity);}db.connection.commit();}assertEquals(400,h.json("POST","/api/openservice/field-availability",availability(h,"TaskOther",true),auth("admin")).statusCode());available(h,"TaskOne",false);assertEquals(200,objects(result(h.get("/api/openservice/field-availability",auth("admin"))).get("entries")).size());
 }
}
